INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', 'ことわざ', NULL, '次のことわざの意味として、最も適切なものはどれか。

「石の上にも三年」', NULL, '["辛抱強く続ければ、いずれ成果が得られるということ","石のように固い意志を持てば何でも実現できるということ","三年ごとに新しいことに挑戦すべきだということ","古いものほど価値が高まるということ","準備に時間をかけすぎると機会を逃すということ"]', 0, '["冷たい石の上でも三年座り続ければ暖まるということから、たとえつらくても、辛抱強く続けていれば、いずれ必ず成果が得られるということを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: ことわざ）');
