「灯台下暗し」', NULL, '["身近なことほど、かえって気づきにくいものだということ","暗い場所ほど、危険が潜んでいるということ","遠くの物事に気を取られ、目の前の危険に気づかないこと","灯りをともせば、どんな暗闇も照らせるということ","準備を怠ると、いざという時に困るということ"]', 0, '["灯台はその周囲を照らすが、灯台の真下は影になって暗いことから、身近なことや、すぐそばにあるものは、かえって気づきにくいものだということを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: ことわざ）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', 'ことわざ', NULL, '次のことわざの意味として、最も適切なものはどれか。

「急がば回れ」', NULL, '["急ぐときほど、安全で確実な方法を選んだほうが結局は早いということ","急いでいるときは、多少の危険を冒しても構わないということ","遠回りをすればするほど、多くの経験が得られるということ","焦って行動すると、必ず失敗するということ","目的地までの近道を、常に探すべきだということ"]', 0, '["急いでいるときほど、危険な近道より、時間はかかっても安全で確実な道を選んだほうが、結局は早く目的を達成できるということを意味する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型・言語: ことわざ）');
